static lstr L5271 = {-1, 448, "// std/internal/entropy. A seed from the operating system's random source.\012#include <time.h>\012\012static int64_t narra_entropy_seed(void) {\012  uint64_t seed = 0;\012  FILE* source = fopen(\"/dev/urandom\", \"rb\");\012  if (source != NULL) {\012    if (fread(&seed, sizeof seed, 1, source) != 1) seed = 0;\012    fclose(source);\012  }\012  if (seed == 0) {\012    seed = (uint64_t)time(NULL) * 6364136223846793005ULL + (uint64_t)(uintptr_t)&seed;\012  }\012  return (int64_t)seed;\012}\012"};
